const fmt = (v) => v == null ? "—" : String(v).replace(".", ",");
const shortDate = (s) => formatDate(s);
const statusNames = { pending: "Очікує", approved: "Підтверджено", rejected: "Відхилено", open: "Відкрита", closed: "Закрита", active: "Активний", inactive: "Неактивний", graduated: "Випускник" };
function Badge({ value }) { return <span className={"badge " + value}>{statusNames[value] || value}</span>; }
function Empty({ title = "Поки немає записів", text = "Змініть пошук або фільтр." }) { return <div className="empty"><BookOpen/><h3>{title}</h3><p>{text}</p></div>; }
function Metric({ label, value, note, Icon = BarChart3 }) { return <section className="stat"><div className="stat-label">{label}<Icon size={18}/></div><strong>{value}</strong><small>{note}</small></section>; }
function Head({ eyebrow, title, lead, action }) { return <div className="page-heading"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1>{lead && <p className="muted">{lead}</p>}</div>{action}</div>; }
function gradeFor(db, studentId, lessonId) { return db.grades.find((g) => g.student_id === studentId && g.lesson_id === lessonId); }
function assignmentName(db, a) { return (db.disciplines.find((d) => d.discipline_id === a.discipline_id)?.name || "Дисципліна") + " · " + (a.target_name_at_assignment || (a.stream_id ? db.streams.find((s) => s.stream_id === a.stream_id)?.name || "Потік" : db.groups.find((g) => g.group_id === a.group_id)?.name || "Група")); }
function saveCSV(name, rows) {
  const cell = (v) => { let text = String(v ?? ""); if (/^[=+\-@\t\r]/.test(text)) text = "'" + text; return '"' + text.replaceAll('"', '""') + '"'; };
  const csv = "\ufeff" + rows.map((row) => row.map(cell).join(";")).join("\r\n");
  const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
  const a = document.createElement("a"); a.href = url; a.download = name; a.click(); URL.revokeObjectURL(url);
}

const loginErrors = { domain: "Дозволено лише облікові записи @pnu.edu.ua та @cnu.edu.ua.", not_registered: "Цей обліковий запис не зареєстровано адміністратором.", state: "Сеанс входу завершився. Спробуйте ще раз.", google: "Google не підтвердив вхід. Спробуйте ще раз." };
(function consumeAuthCallback() {
  if (!location.hash.startsWith("#/auth/callback")) return;
  const params = new URLSearchParams(location.hash.split("?")[1] || "");
  const token = params.get("token");
  try {
    if (token) {
      sessionStorage.setItem("uspikh-token", token);
      sessionStorage.setItem("uspikh-user-id", String(JSON.parse(atob(token.split(".")[1].replace(/-/g, "+").replace(/_/g, "/"))).sub));
    } else sessionStorage.setItem("uspikh-login-error", loginErrors[params.get("error")] || "Не вдалося увійти.");
  } catch { sessionStorage.setItem("uspikh-login-error", "Не вдалося увійти."); }
  history.replaceState(null, "", location.pathname + "#overview");
})();

