  const curatorPicker = <><label className="field-inline">Пошук групи<input type="search" aria-label="Пошук групи куратора" placeholder="Назва групи" value={curatorGroupSearch} onChange={(e)=>setCuratorGroupSearch(e.target.value)}/></label><label className="field-inline">Група<select aria-label="Група куратора" value={selectedCuratorGroup?.group_id || ""} onChange={(e)=>setCuratorGroupId(Number(e.target.value))}>{curatorGroups.filter((g)=>g.group_id===selectedCuratorGroup?.group_id||g.name.toLocaleLowerCase("uk").includes(curatorGroupSearch.trim().toLocaleLowerCase("uk"))).map((g)=><option key={g.group_id} value={g.group_id}>{g.name}</option>)}</select></label></>;
